const rows = $input.all();

const formatDate = (dateStr) => {
  if (!dateStr) return '—';
  const d = new Date(dateStr);
  return d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
};

const today = new Date();
const reportDate = today.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
const subjectDate = today.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: '2-digit' }).replace(/\//g, '-');

let tableRows = '';

rows.forEach((row, index) => {
  const r = row.json;
  const stepNo = r['Step No.'] || (index + 1);
  const task = r['Task Description'] || '—';
  const status = r['Status'] || '—';
  const doneBy = r['Done By'] || '—';
  const dateGiven = formatDate(r['Date Given']);
  const targetDate = formatDate(r['Target Date']);
  const remarks = r['Remarks'] || '—';
  const duration = `${dateGiven} → ${targetDate}`;

  tableRows += `
    <tr>
      <td style="padding:8px;border:1px solid #ddd;text-align:center;">${stepNo}</td>
      <td style="padding:8px;border:1px solid #ddd;">${task}</td>
      <td style="padding:8px;border:1px solid #ddd;">${status}</td>
      <td style="padding:8px;border:1px solid #ddd;">${doneBy}</td>
      <td style="padding:8px;border:1px solid #ddd;">${duration}</td>
      <td style="padding:8px;border:1px solid #ddd;">${remarks}</td>
    </tr>`;
});

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Daily Report — ${reportDate}</title>
</head>
<body style="font-family:Arial,sans-serif;font-size:14px;color:#000;padding:16px;margin:0;">
  <p>Dear GM,</p>
  <p><strong>Daily Report — ${reportDate}</strong></p>
  <div style="overflow-x:auto;-webkit-overflow-scrolling:touch;width:100%;">
    <table style="border-collapse:collapse;min-width:600px;width:100%;table-layout:fixed;word-wrap:break-word;">
      <thead>
        <tr>
          <th style="padding:8px;border:1px solid #ddd;border-bottom:2px solid #000;text-align:center;width:5%;">#</th>
          <th style="padding:8px;border:1px solid #ddd;border-bottom:2px solid #000;width:25%;">Task Description</th>
          <th style="padding:8px;border:1px solid #ddd;border-bottom:2px solid #000;width:12%;">Status</th>
          <th style="padding:8px;border:1px solid #ddd;border-bottom:2px solid #000;width:10%;">Done By</th>
          <th style="padding:8px;border:1px solid #ddd;border-bottom:2px solid #000;width:18%;">Duration</th>
          <th style="padding:8px;border:1px solid #ddd;border-bottom:2px solid #000;width:30%;">Remarks</th>
        </tr>
      </thead>
      <tbody>
        ${tableRows}
      </tbody>
    </table>
  </div>
  <br>
  <p>Regards,<br>Liane</p>
</body>
</html>`;

return [{ json: { html, reportDate, subjectDate } }];

